import { useTranslation } from 'react-i18next'
import { useWorkspaceStore } from '@/app/store/workspaceStore'
import { useTenant } from '@/app/providers/TenantProvider'

export function ContextPanel() {
  const { t } = useTranslation('shell')
  const { tenantId, workplaceId, projectId, objectiveId, userRole } = useWorkspaceStore()
  const { manifest } = useTenant()

  const items = [
    { label: t('tenant'), value: manifest?.name ?? tenantId },
    { label: t('workplace'), value: workplaceId },
    { label: t('project'), value: projectId },
    { label: t('objective'), value: objectiveId },
    { label: 'Role', value: userRole },
  ]

  return (
    <div className="p-4 flex flex-col gap-3 overflow-y-auto h-full">
      <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide">
        {t('currentContext')}
      </p>
      <div className="flex flex-col gap-2">
        {items.map((item) => (
          <div key={item.label} className="flex flex-col">
            <span className="text-xs text-muted-foreground">{item.label}</span>
            <span className="text-sm font-medium truncate">
              {item.value ?? <span className="text-muted-foreground italic">—</span>}
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}
